const { chromium } = require('playwright');
(async () => {
  let result = { passed: false, error: null, screenshot: null };
  const browser = await chromium.launch({ headless: true });
  const page = await browser.newPage();
  try {
    await page.goto('http://localhost:5173/login');
    await page.fill('input[type="email"]', 'employee@unichronic.com');
    await page.fill('input[type="password"]', 'employee123!');
    await page.click('button[type="submit"]');
    await page.waitForURL('http://localhost:5173/dashboard/employee');

    await page.click('text=Apply for Leave');
    await page.waitForSelector('text=Submit Leave Request');

    await page.selectOption('select[name="leaveType"]', { index: 1 });

    const nextMonth = new Date();
    nextMonth.setMonth(nextMonth.getMonth() + 2);
    const start = nextMonth.toISOString().split('T')[0];
    nextMonth.setDate(nextMonth.getDate() + 1);
    const end = nextMonth.toISOString().split('T')[0];

    await page.fill('input[name="startDate"]', start);
    await page.fill('input[name="endDate"]', end);
    await page.fill('textarea[name="reason"]', 'Family vacation');

    await page.click('button[type="submit"]:has-text("Submit Request")');

    await page.waitForSelector('text=Leave request submitted successfully!', { timeout: 5000 });
    result.passed = true;
  } catch (err) {
    result.error = err.toString();
    await page.screenshot({ path: 'tc001-error.png' });
    result.screenshot = 'tc001-error.png';
  } finally {
    await browser.close();
    console.log(JSON.stringify(result));
  }
})();

